-- Produto enviado pelo Daniel: Hidramais Loção Desodorante Ameixa Negra 500ml
-- Preço R$ 0,00 por enquanto (definido depois da reunião com o contador) => cadastrado INATIVO:
-- o sistema só permite ativar produto com preço de venda. Impostos em branco.

INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Hidramais', true, 10, now(), now())
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "products" ("id", "sku", "name", "brandId", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "internalNotes", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'HID-AMEIXA-500', 'Loção Desodorante Ameixa Negra 500ml', b."id", 'UN', 0, 0, 0, 0, 0, false,
       'Preço a definir (reunião com o contador). Informe o preço de venda para ativar.', now(), now()
  FROM "brands" b WHERE b."name" = 'Hidramais'
ON CONFLICT ("sku") DO NOTHING;

-- Foto com fundo transparente (WebP)
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'hid-ameixa-negra-500.webp', 'image/webp', 22930, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'hid-ameixa-negra-500.webp');

INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'hid-ameixa-negra-500.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'HID-AMEIXA-500'
   AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
